const jobId = String($json.job_id ?? '')
  .trim()
  .toLowerCase();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!uuidPattern.test(jobId)) {
  throw new Error('job_id must be a valid UUID');
}

return [{ json: { job_id: jobId } }];

const job = $input.first().json;

if (!job.job_exists) {
  throw new Error(`Job ${job.requested_job_id} was not found`);
}

const normalVisualState =
  job.status === 'processing' &&
  ['voiceover', 'visuals'].includes(job.current_stage);

const retryVisualState =
  job.status === 'failed' &&
  job.current_stage === 'visuals';

if (!normalVisualState && !retryVisualState) {
  throw new Error(
    `Job ${job.job_id} is not eligible for visual sourcing: ` +
    `status=${job.status}, current_stage=${job.current_stage}`
  );
}

const requiredScenesByDuration = {
  15: 4,
  30: 8,
  45: 12,
  60: 15,
};

const requiredSceneCount =
  requiredScenesByDuration[Number(job.target_duration_seconds)];

if (!requiredSceneCount) {
  throw new Error(
    `Unsupported target_duration_seconds: ${job.target_duration_seconds}`
  );
}

if (!Array.isArray(job.scenes)) {
  throw new Error(`Job ${job.job_id} scenes are unavailable`);
}

if (
  Number(job.scene_count) !== requiredSceneCount ||
  job.scenes.length !== requiredSceneCount
) {
  throw new Error(
    `Job ${job.job_id} must have exactly ${requiredSceneCount} scenes`
  );
}

const seenQueries = new Set();
let pendingSceneCount = 0;
let completedSceneCount = 0;

for (let index = 0; index < job.scenes.length; index++) {
  const scene = job.scenes[index];
  const expected = index + 1;

  if (Number(scene.scene_number) !== expected) {
    throw new Error(
      `Invalid scene_number at position ${expected}: received ${scene.scene_number}`
    );
  }

  for (const field of [
    'scene_id',
    'narration',
    'visual_description',
    'visual_query',
  ]) {
    if (
      typeof scene[field] !== 'string' ||
      scene[field].trim() === ''
    ) {
      throw new Error(
        `Scene ${expected} is missing ${field}`
      );
    }
  }

  const query = scene.visual_query.trim();

  if (query.length > 100) {
    throw new Error(
      `Scene ${expected} visual_query exceeds 100 characters`
    );
  }

  const queryKey = query.toLowerCase();
  if (seenQueries.has(queryKey)) {
    throw new Error(
      `Duplicate visual_query at scene ${expected}`
    );
  }
  seenQueries.add(queryKey);

  if (!['factual', 'generic'].includes(scene.visual_subject_type)) {
    throw new Error(
      `Scene ${expected} has invalid visual_subject_type`
    );
  }

  const audioPath =
    typeof scene.audio_path === 'string'
      ? scene.audio_path.trim()
      : '';
  const duration = Number(scene.duration_seconds);

  if (
    !audioPath ||
    !Number.isFinite(duration) ||
    duration <= 0
  ) {
    throw new Error(
      `Scene ${expected} does not have completed voiceover`
    );
  }

  const visualPath =
    typeof scene.visual_path === 'string'
      ? scene.visual_path.trim()
      : '';
  const assetCount = Number(scene.asset_count ?? 0);

  if (!Number.isInteger(assetCount) || assetCount < 0) {
    throw new Error(
      `Scene ${expected} has invalid asset_count`
    );
  }

  if (visualPath) {
    if (assetCount < 1) {
      throw new Error(
        `Scene ${expected} has visual_path without asset metadata`
      );
    }
    completedSceneCount++;
  } else {
    if (assetCount !== 0) {
      throw new Error(
        `Scene ${expected} has asset metadata without visual_path`
      );
    }
    pendingSceneCount++;
  }
}

if (
  job.current_stage === 'voiceover' &&
  completedSceneCount > 0
) {
  throw new Error(
    `Job ${job.job_id} has visual output before visual stage start`
  );
}

const alreadyComplete =
  pendingSceneCount === 0 &&
  completedSceneCount === requiredSceneCount;

if (
  alreadyComplete &&
  job.current_stage !== 'visuals'
) {
  throw new Error(
    `Job ${job.job_id} is visually complete but current_stage is ${job.current_stage}`
  );
}

return [{
  json: {
    ...job,
    required_scene_count: requiredSceneCount,
    pending_scene_count: pendingSceneCount,
    completed_scene_count: completedSceneCount,
    already_complete: alreadyComplete,
  },
}];

const transition = $input.first().json;
const job = $('Require Eligible Visual Job').first().json;

if (transition.ready_to_run !== true) {
  throw new Error(
    `Job ${job.job_id} could not enter or resume visuals stage`
  );
}

if (String(transition.job_id) !== String(job.job_id)) {
  throw new Error('Visual stage transition job_id mismatch');
}

if (
  transition.status !== 'processing' ||
  transition.current_stage !== 'visuals'
) {
  throw new Error(
    `Unexpected visual state: status=${transition.status}, ` +
    `current_stage=${transition.current_stage}`
  );
}

const pendingScenes = job.scenes.filter((scene) => {
  const visualPath =
    typeof scene.visual_path === 'string'
      ? scene.visual_path.trim()
      : '';
  return !visualPath;
});

if (pendingScenes.length === 0) {
  throw new Error(
    `Job ${job.job_id} has no pending visual scenes`
  );
}

return pendingScenes.map((scene) => ({
  json: {
    job_id: job.job_id,
    scene_id: scene.scene_id,
    scene_number: Number(scene.scene_number),
    narration: scene.narration.trim(),
    visual_description: scene.visual_description.trim(),
    visual_query: scene.visual_query.trim(),
    visual_subject_type: scene.visual_subject_type,
  },
}));

function cleanText(value) {
  return String(value ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1000);
}

const response = $json;
const scene = $('Prepare Wikimedia Query').item.json;
const pages = Array.isArray(response?.query?.pages) ? response.query.pages : [];
const supported = new Set(['image/jpeg','image/png','image/webp','image/gif','image/svg+xml']);
const maxBytes = 24 * 1024 * 1024;
const candidatePool = [];

for (let index = 0; index < pages.length && candidatePool.length < 10; index++) {
  const page = pages[index] ?? {};
  const info = page?.imageinfo?.[0] ?? {};
  const mime = String(info.mime ?? '').toLowerCase();
  const downloadUrl = String(info.url ?? '').trim();
  const previewUrl = String(info.thumburl ?? info.url ?? '').trim();
  const width = Number(info.width);
  const height = Number(info.height);
  const size = Number(info.size ?? 0);
  const dimensionsUsable = mime === 'image/svg+xml' ? width >= 100 && height >= 100 : width >= 320 && height >= 320;
  if (!supported.has(mime) || !downloadUrl || !previewUrl || !Number.isFinite(width) || !Number.isFinite(height) || !dimensionsUsable || (Number.isFinite(size) && size > maxBytes)) continue;
  const ext = info.extmetadata ?? {};
  const title = String(page.title ?? '').trim();
  const sourceUrl = String(info.descriptionurl ?? '').trim() || `https://commons.wikimedia.org/wiki/${encodeURIComponent(title.replace(/\s+/g, '_'))}`;
  candidatePool.push({
    candidate_id: title || `wikimedia-${index + 1}`,
    preview_url: previewUrl,
    provider: 'wikimedia',
    provider_asset_id: title,
    download_url: downloadUrl,
    source_url: sourceUrl,
    author: cleanText(ext?.Artist?.value || ext?.Credit?.value) || null,
    license: cleanText(ext?.LicenseShortName?.value) || null,
    license_url: cleanText(ext?.LicenseUrl?.value) || null,
    metadata: { provider_rank:index+1, provider_query:scene.wikimedia_query || scene.visual_query, source_title:title, source_mime:mime, source_width:width, source_height:height, source_bytes:Number.isFinite(size)?size:null },
  });
}

return { json: { ...scene, candidate_found:candidatePool.length>0, candidate_pool:candidatePool, fallback_reason:candidatePool.length>0?null:'No deterministically usable Wikimedia Commons candidate was available' } };

const response = $json;
const scene = $('Prepare Visual Items').item.json;
const hits = Array.isArray(response?.hits) ? response.hits : [];
const maxBytes = 24 * 1024 * 1024;
const candidatePool = [];
for (let index = 0; index < hits.length && candidatePool.length < 10; index++) {
  const hit = hits[index] ?? {};
  const downloadUrl = String(hit.largeImageURL ?? hit.webformatURL ?? '').trim();
  const previewUrl = String(hit.webformatURL ?? hit.previewURL ?? '').trim();
  const width = Number(hit.imageWidth ?? 0);
  const height = Number(hit.imageHeight ?? 0);
  const size = Number(hit.imageSize ?? 0);
  if (!downloadUrl || !previewUrl || !Number.isFinite(width) || !Number.isFinite(height) || width < 320 || height < 320 || (Number.isFinite(size) && size > maxBytes)) continue;
  candidatePool.push({
    candidate_id:String(hit.id ?? `pixabay-${index+1}`), preview_url:previewUrl, provider:'pixabay', provider_asset_id:String(hit.id ?? ''), download_url:downloadUrl,
    source_url:String(hit.pageURL ?? '').trim() || null, author:String(hit.user ?? '').trim() || null,
    license:'Pixabay Content License', license_url:'https://pixabay.com/service/license-summary/',
    metadata:{ provider_rank:index+1, tags:String(hit.tags ?? ''), source_width:width, source_height:height, source_bytes:Number.isFinite(size)?size:null },
  });
}
return { json:{ ...scene, candidate_found:candidatePool.length>0, candidate_pool:candidatePool, fallback_reason:candidatePool.length>0?null:'No deterministically usable Pixabay candidate was available' } };

const scene = $('Prepare Visual Items').item.json;
const errorItem = $json ?? {};

let reason =
  errorItem.error?.message ||
  errorItem.error?.description ||
  errorItem.errorMessage ||
  errorItem.message ||
  'Pixabay search failed';

return {
  json: {
    ...scene,
    fallback_reason: String(reason).slice(0, 1000),
  },
};

const response = $json;
const scene = $('Prepare Visual Items').item.json;
const photos = Array.isArray(response?.photos) ? response.photos : [];
const candidatePool = [];
for (let index = 0; index < photos.length && candidatePool.length < 10; index++) {
  const photo = photos[index] ?? {};
  const downloadUrl = String(photo?.src?.original ?? '').trim();
  const previewUrl = String(photo?.src?.medium ?? photo?.src?.small ?? photo?.src?.original ?? '').trim();
  const width = Number(photo.width ?? 0);
  const height = Number(photo.height ?? 0);
  if (!downloadUrl || !previewUrl || !Number.isFinite(width) || !Number.isFinite(height) || width < 320 || height < 320) continue;
  candidatePool.push({
    candidate_id:String(photo.id ?? `pexels-${index+1}`), preview_url:previewUrl, provider:'pexels', provider_asset_id:String(photo.id ?? ''), download_url:downloadUrl,
    source_url:String(photo.url ?? '').trim() || null, author:String(photo.photographer ?? '').trim() || null,
    license:'Pexels License', license_url:'https://www.pexels.com/license/',
    metadata:{ provider_rank:index+1, alt:String(photo.alt ?? ''), source_width:width, source_height:height },
  });
}
return { json:{ ...scene, candidate_found:candidatePool.length>0, candidate_pool:candidatePool, fallback_reason:candidatePool.length>0?null:'No deterministically usable Pexels candidate was available' } };

const item = $json;

if (
  item.candidate_found !== true ||
  typeof item.download_url !== 'string' ||
  item.download_url.trim() === ''
) {
  throw new Error('Selected visual candidate is incomplete');
}

return { json: item };

const visualPath =
  typeof $json.visual_path === 'string'
    ? $json.visual_path.trim()
    : '';
const width = Number($json.width);
const height = Number($json.height);
const bytes = Number($json.bytes);

if (!visualPath) {
  throw new Error(
    'media-worker response is missing visual_path'
  );
}

if (
  !Number.isFinite(width) ||
  width <= 0 ||
  !Number.isFinite(height) ||
  height <= 0
) {
  throw new Error(
    'media-worker returned invalid visual dimensions'
  );
}

if (!Number.isFinite(bytes) || bytes <= 0) {
  throw new Error(
    'media-worker returned invalid visual byte size'
  );
}

return {
  json: {
    ...$json,
    visual_path: visualPath,
    width,
    height,
    bytes,
  },
};

const stored = $json;
const selected = $('Prepare Selected Download').item.json;

return {
  json: {
    job_id: selected.job_id,
    scene_id: selected.scene_id,
    scene_number: selected.scene_number,
    provider: selected.provider,
    provider_asset_id: selected.provider_asset_id || null,
    source_url: selected.source_url || null,
    author: selected.author || null,
    license: selected.license || null,
    license_url: selected.license_url || null,
    visual_path: stored.visual_path,
    metadata: {
      ...(selected.metadata ?? {}),
      normalized_width: Number(stored.width),
      normalized_height: Number(stored.height),
      normalized_codec: stored.codec_name ?? null,
      normalized_bytes: Number(stored.bytes),
      source_content_type: stored.source_content_type ?? null,
      stored_by: 'media-worker',
    },
  },
};

const selected = $('Prepare Selected Download').item.json;
const errorItem = $json ?? {};

const candidates = [
  errorItem.error?.message,
  errorItem.error?.description,
  errorItem.error,
  errorItem.errorMessage,
  errorItem.message,
];

let message = candidates.find(
  (value) =>
    typeof value === 'string' &&
    value.trim() !== ''
);

if (!message) {
  try {
    message = JSON.stringify(errorItem);
  } catch {
    message = 'External visual download/store failed';
  }
}

return {
  json: {
    ...selected,
    retry_pexels: selected.provider === 'pixabay',
    fallback_reason:
      String(message || 'External visual failed')
        .trim()
        .slice(0, 1000),
  },
};

const scene = $('Prepare Visual Items').item.json;
const incoming = $json ?? {};

const candidates = [
  incoming.fallback_reason,
  incoming.error?.message,
  incoming.error?.description,
  incoming.error,
  incoming.errorMessage,
  incoming.message,
];

let reason = candidates.find(
  (value) =>
    typeof value === 'string' &&
    value.trim() !== ''
);

if (!reason) {
  reason = 'No acceptable external visual asset was available';
}

const query = String(scene.visual_query ?? '').toLowerCase();
const locationErrorIntent =
  /\b(navigation|location|position)\b/i.test(query) &&
  /\b(inaccurate|wrong|error|drift)\b/i.test(query);

return {
  json: {
    ...scene,
    fallback_kind: locationErrorIntent ? 'location_error' : 'text',
    fallback_reason: String(reason).trim().slice(0, 1000),
  },
};

const visualPath =
  typeof $json.visual_path === 'string'
    ? $json.visual_path.trim()
    : '';
const width = Number($json.width);
const height = Number($json.height);
const bytes = Number($json.bytes);

if ($json.fallback !== true || !visualPath) {
  throw new Error(
    'media-worker fallback response is invalid'
  );
}

if (
  !Number.isFinite(width) ||
  width <= 0 ||
  !Number.isFinite(height) ||
  height <= 0 ||
  !Number.isFinite(bytes) ||
  bytes <= 0
) {
  throw new Error(
    'media-worker fallback dimensions/bytes are invalid'
  );
}

return {
  json: {
    ...$json,
    visual_path: visualPath,
    width,
    height,
    bytes,
  },
};

const stored = $json;
const scene = $('Prepare Fallback Context').item.json;

return {
  json: {
    job_id: scene.job_id,
    scene_id: scene.scene_id,
    scene_number: scene.scene_number,
    provider: 'local_fallback',
    provider_asset_id: null,
    source_url: null,
    author: null,
    license: null,
    license_url: null,
    visual_path: stored.visual_path,
    metadata: {
      fallback: true,
      fallback_kind: stored.fallback_kind ?? scene.fallback_kind ?? 'text',
      reason: scene.fallback_reason,
      normalized_width: Number(stored.width),
      normalized_height: Number(stored.height),
      normalized_codec: stored.codec_name ?? null,
      normalized_bytes: Number(stored.bytes),
      stored_by: 'media-worker',
    },
  },
};

const result = $json;

if (!result.job_exists) {
  throw new Error(
    `Job ${result.job_id} was not found during visual completion check`
  );
}

if (
  result.status !== 'processing' ||
  result.current_stage !== 'visuals'
) {
  throw new Error(
    `Unexpected job state after visuals: ` +
    `status=${result.status}, current_stage=${result.current_stage}`
  );
}

if (result.all_visuals_ready !== true) {
  throw new Error(
    `Visual sourcing is incomplete for job ${result.job_id}: ` +
    `ready=${result.ready_scene_count}, ` +
    `total=${result.total_scene_count}, ` +
    `required=${result.required_scene_count}, ` +
    `incomplete=${result.incomplete_scene_count}`
  );
}

return {
  json: {
    job_id: result.job_id,
    status: result.status,
    current_stage: result.current_stage,
    scene_count: Number(result.total_scene_count),
    visuals_complete: true,
  },
};

const errorItem = $input.first()?.json ?? {};
const job = $('Require Eligible Visual Job').first().json;

if (
  typeof job.job_id !== 'string' ||
  job.job_id.trim() === ''
) {
  throw new Error(
    'Validated job_id is unavailable while recording visual failure'
  );
}

const candidates = [
  errorItem.error?.message,
  errorItem.error?.description,
  errorItem.error,
  errorItem.errorMessage,
  errorItem.errorDescription,
  errorItem.message,
];

let message = candidates.find(
  (value) =>
    typeof value === 'string' &&
    value.trim() !== ''
);

if (!message) {
  try {
    message = JSON.stringify(errorItem);
  } catch {
    message = '';
  }
}

message = String(
  message || 'Unknown visual sourcing stage failure'
)
  .trim()
  .slice(0, 4000);

return [{
  json: {
    job_id: job.job_id,
    last_error: message,
  },
}];

const rankings = $input.all();
const pools = $('Prepare Wikimedia Candidate Pool').all().map((item) => item.json);
const poolByQuery = new Map();
for (const pool of pools) {
  const key = String(pool.visual_query ?? '').trim().toLowerCase();
  if (key) poolByQuery.set(key, pool);
}
const records = rankings.map((item, inputIndex) => {
  const ranking = item.json;
  const key = String(ranking.query ?? '').trim().toLowerCase();
  const pool = poolByQuery.get(key);
  if (!pool) throw new Error(`Semantic ranking pool is unavailable for query: ${ranking.query ?? ''}`);
  return { ranking, pool, inputIndex };
});
records.sort((a,b) => Number(a.pool.scene_number) - Number(b.pool.scene_number));
const usedAssets = new Set();
const outputs = [];
for (const record of records) {
  const { ranking, pool, inputIndex } = record;
  if (!Array.isArray(pool.candidate_pool) || pool.candidate_pool.length === 0) throw new Error('Visual candidate pool is unavailable during semantic selection');
  if (!Array.isArray(ranking.ranked) || ranking.ranked.length === 0) throw new Error('media-worker semantic ranking returned no usable candidate');
  let selected = null;
  let selectedRank = null;
  let duplicateUnavoidable = false;
  for (const ranked of ranking.ranked) {
    if (!ranked || typeof ranked.candidate_id !== 'string' || !Number.isFinite(Number(ranked.score))) continue;
    const candidate = pool.candidate_pool.find((entry) => String(entry.candidate_id) === String(ranked.candidate_id));
    if (!candidate) continue;
    const assetKey = `${candidate.provider}:${String(candidate.provider_asset_id ?? candidate.candidate_id)}`;
    if (!usedAssets.has(assetKey)) {
      selected = candidate;
      selectedRank = ranked;
      usedAssets.add(assetKey);
      break;
    }
  }
  if (!selected) {
    const ranked = ranking.ranked[0];
    selected = pool.candidate_pool.find((entry) => String(entry.candidate_id) === String(ranked.candidate_id));
    selectedRank = ranked;
    duplicateUnavoidable = true;
  }
  if (!selected || !selectedRank) throw new Error('Semantic ranking winner does not exist in the trusted provider pool');
  outputs.push({
    json: {
      job_id:pool.job_id, scene_id:pool.scene_id, scene_number:pool.scene_number,
      narration:pool.narration, visual_description:pool.visual_description, visual_query:pool.visual_query,
      visual_subject_type:pool.visual_subject_type, candidate_found:true,
      provider:selected.provider, provider_asset_id:selected.provider_asset_id, download_url:selected.download_url,
      source_url:selected.source_url, author:selected.author, license:selected.license, license_url:selected.license_url,
      metadata:{ ...selected.metadata, semantic_model:String(ranking.model ?? ''), semantic_dtype:String(ranking.dtype ?? ''), semantic_score:Number(selectedRank.score), semantic_rank:Number(selectedRank.rank ?? 1), semantic_candidate_count:Number(ranking.candidate_count ?? ranking.ranked.length), semantic_duplicate_unavoidable:duplicateUnavoidable }
    },
    pairedItem:{ item:inputIndex }
  });
}
outputs.sort((a,b) => Number(a.json.scene_number) - Number(b.json.scene_number));
return outputs;

